package com.ecoflowscheduler.widget;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;

/**
 * Mains/outage timeline from history samples: a port of ecoflow_app/power.py (and the schedule letters of
 * schedule.py). Pure Java. SegmentsTest checks it against output generated by the Python code.
 * Unknown numbers are NaN (Python's None).
 */
public final class Segments {
    public static final int NODATA = 0, GRID = 1, OUTAGE = 2, MAYBE = 3;

    static final double MAX_GAP = 180, COVER_AFTER_SAMPLE = 60, GRID_MIN_AC_WATTS = 5;
    static final double STALE_REPLAY_GAP = 600, STALE_SOC_TOL = 0.3, STALE_CONTRADICTION = 5;
    static final double TRAILING_MAX = 7200;

    private Segments() {
    }

    public static final class Row {
        public long ts;
        public double soc = Double.NaN, in, out, acIn, acOut, limit, temp;
        public int grid = -1;          // 1 mains, 0 none, -1 unknown
        public double chgMin = Double.NaN, dsgMin = Double.NaN;   // time estimates, only in the phone's own readings
        public String src = "";

        boolean mains() {
            return grid < 0 ? acIn >= GRID_MIN_AC_WATTS : grid == 1;
        }
    }

    public static final class Seg {
        public double start, end, outKwh, inKwh;
        public int kind;
        public double socStart = Double.NaN, socEnd = Double.NaN;
        public final List<double[]> est = new ArrayList<>();      // spans estimated from neighbouring data
        public final List<double[]> manual = new ArrayList<>();   // spans without data that were marked by hand

        Seg(double start, double end, int kind) {
            this.start = start;
            this.end = end;
            this.kind = kind;
        }

        Seg copy() {
            Seg s = new Seg(start, end, kind);
            s.outKwh = outKwh;
            s.inKwh = inKwh;
            s.socStart = socStart;
            s.socEnd = socEnd;
            s.est.addAll(est);
            s.manual.addAll(manual);
            return s;
        }

        public double seconds() {
            return end - start;
        }

        public double manualSeconds() {
            double sum = 0;
            for (double[] m : manual) sum += m[1] - m[0];
            return sum;
        }

        boolean startEstimated() {
            for (double[] e : unmeasured()) {
                if (e[0] <= start + 1) return true;
            }
            return false;
        }

        boolean endEstimated() {
            for (double[] e : unmeasured()) {
                if (e[1] >= end - 1) return true;
            }
            return false;
        }

        private List<double[]> unmeasured() {
            List<double[]> all = new ArrayList<>(est);
            all.addAll(manual);
            return all;
        }
    }

    /** A manual statement about a stretch without data: kind "grid", "outage" or "clear". */
    public static final class Mark {
        public final long start, end;
        public final String kind, by;
        public final double at;

        public Mark(long start, long end, String kind, double at, String by) {
            this.start = start;
            this.end = end;
            this.kind = kind;
            this.at = at;
            this.by = by;
        }
    }

    /** Non-overlapping [start, end, GRID|OUTAGE] sorted by time: the newest mark wins, "clear" removes. */
    public static List<double[]> resolveMarks(List<Mark> marks) {
        List<Mark> ordered = new ArrayList<>(marks);
        Collections.sort(ordered, (a, b) -> a.at != b.at ? Double.compare(a.at, b.at)
                : (!a.by.equals(b.by) ? a.by.compareTo(b.by) : Long.compare(a.start, b.start)));
        List<double[]> out = new ArrayList<>();
        for (Mark m : ordered) {
            List<double[]> kept = new ArrayList<>();
            for (double[] x : out) {
                if (x[1] <= m.start || x[0] >= m.end) {
                    kept.add(x);
                    continue;
                }
                if (x[0] < m.start) kept.add(new double[]{x[0], m.start, x[2]});
                if (x[1] > m.end) kept.add(new double[]{m.end, x[1], x[2]});
            }
            if (!"clear".equals(m.kind)) {
                kept.add(new double[]{m.start, m.end, "grid".equals(m.kind) ? GRID : OUTAGE});
            }
            out = kept;
        }
        Collections.sort(out, (a, b) -> Double.compare(a[0], b[0]));
        return out;
    }

    /** Give the marked parts of no-data stretches their kind (see power.apply_marks). Between grid() and fillGaps(). */
    public static List<Seg> applyMarks(List<Seg> segs, List<double[]> marks) {
        List<Seg> out = new ArrayList<>();
        for (int i = 0; i < segs.size(); i++) {
            Seg s = segs.get(i);
            if (s.kind != NODATA) {
                out.add(s);
                continue;
            }
            Seg prev = null, nxt = null;
            for (int j = i - 1; j >= 0 && prev == null; j--) {
                if (segs.get(j).kind != NODATA) prev = segs.get(j);
            }
            for (int j = i + 1; j < segs.size() && nxt == null; j++) {
                if (segs.get(j).kind != NODATA) nxt = segs.get(j);
            }
            double s0 = prev != null ? prev.socEnd : Double.NaN;
            double s1 = nxt != null ? nxt.socStart : s0;
            double cursor = s.start;
            for (double[] m : marks) {
                double a = Math.max(m[0], s.start), b = Math.min(m[1], s.end);
                if (b <= a) continue;
                int kind = (int) m[2];
                if (a > cursor) out.add(new Seg(cursor, a, NODATA));
                Seg src = prev != null && prev.kind == kind ? prev : (nxt != null && nxt.kind == kind ? nxt : null);
                double outW = src != null && src.seconds() > 0 ? src.outKwh * 3.6e6 / src.seconds() : 0;
                double inW = src != null && src.seconds() > 0 ? src.inKwh * 3.6e6 / src.seconds() : 0;
                double endLevel = s1;
                if (kind == OUTAGE && !Double.isNaN(s0) && !Double.isNaN(s1)) endLevel = Math.min(s0, s1);
                Seg f = new Seg(a, b, kind);
                f.outKwh = outW * (b - a) / 3.6e6;
                f.inKwh = inW * (b - a) / 3.6e6;
                f.socStart = lerp(s.start, s.end, s0, endLevel, a);
                f.socEnd = lerp(s.start, s.end, s0, endLevel, b);
                f.manual.add(new double[]{a, b});
                out.add(f);
                cursor = b;
            }
            if (s.end > cursor) out.add(new Seg(cursor, s.end, NODATA));
        }
        return out;
    }

    /** Rows sorted by time. Removes samples that replay an old state after a sleep (see power.drop_stale_samples). */
    public static List<Row> dropStale(List<Row> rows) {
        Set<String> sources = new HashSet<>();
        for (Row r : rows) sources.add(r.src);
        if (sources.size() < 2) return rows;
        Map<String, Row> last = new HashMap<>();
        Map<String, Row> replay = new HashMap<>();
        List<Row> kept = new ArrayList<>();
        for (int i = 0; i < rows.size(); i++) {
            Row r = rows.get(i);
            Row p = last.put(r.src, r);
            if (p == null || Double.isNaN(r.soc) || Double.isNaN(p.soc)) {
                kept.add(r);
                continue;
            }
            boolean same = Math.abs(r.soc - p.soc) <= STALE_SOC_TOL && r.limit == p.limit && r.mains() == p.mains();
            Row ref = replay.get(r.src);
            if (ref != null) {
                if (r.ts - p.ts <= MAX_GAP && Math.abs(r.soc - ref.soc) <= STALE_SOC_TOL && r.mains() == ref.mains()) {
                    continue;
                }
                replay.remove(r.src);
            }
            if (r.ts - p.ts < STALE_REPLAY_GAP || !same) {
                kept.add(r);
                continue;
            }
            Row other = null;
            for (int j = i - 1; j >= 0 && rows.get(j).ts > p.ts; j--) {
                if (!Objects.equals(rows.get(j).src, r.src)) {
                    other = rows.get(j);
                    break;
                }
            }
            if (other != null && !Double.isNaN(other.soc)
                    && (Math.abs(other.soc - r.soc) > STALE_CONTRADICTION || other.mains() != r.mains())) {
                replay.put(r.src, p);
                continue;
            }
            kept.add(r);
        }
        return kept;
    }

    /** 'charging' | 'discharging' | 'full' | 'ongrid'; `prev` adds hysteresis (see power.state_of). */
    public static String stateOf(double soc, double in, double out, boolean mains, String prev) {
        double net = in - out;
        if (!mains) return net > 3 ? "charging" : "discharging";
        if (soc >= 99.5 || ("full".equals(prev) && soc >= 98)) return net >= -3 ? "full" : "discharging";
        if (net > 3 || ("charging".equals(prev) && net > 0)) return "charging";
        if (net < -3) return "discharging";
        return "ongrid";
    }

    public static final class State {
        public String name;
        public long since;
    }

    /** Current state and when the current run started; null for no rows. */
    public static State stateSince(List<Row> rows) {
        State s = null;
        for (Row r : rows) {
            String name = stateOf(Double.isNaN(r.soc) ? 0 : r.soc, r.in, r.out, r.mains(), s == null ? null : s.name);
            if (s == null || !name.equals(s.name)) {
                s = new State();
                s.name = name;
                s.since = r.ts;
            }
        }
        return s;
    }

    private static double lerp(double t0, double t1, double v0, double v1, double t) {
        if (Double.isNaN(v0) || Double.isNaN(v1)) return Double.NaN;
        if (t1 <= t0) return v0;
        return v0 + (v1 - v0) * (t - t0) / (t1 - t0);
    }

    /** Cover [t0, min(t1, now)] with mains / outage / no-data segments. */
    public static List<Seg> grid(List<Row> rows, double t0, double t1, double now) {
        List<Seg> out = new ArrayList<>();
        double endLimit = Math.min(t1, now);
        if (endLimit <= t0) return out;
        double cursor = t0;
        for (int i = 0; i < rows.size(); i++) {
            Row r = rows.get(i);
            double ts = r.ts;
            boolean hasNext = i + 1 < rows.size();
            double nxt = hasNext ? rows.get(i + 1).ts : 0;
            double segEnd;
            boolean toNext = false;
            if (hasNext && nxt - ts <= MAX_GAP) {
                segEnd = nxt;
                toNext = true;
            } else if (!hasNext && now - ts <= MAX_GAP) {
                segEnd = now;
            } else {
                segEnd = ts + COVER_AFTER_SAMPLE;
                toNext = hasNext && segEnd == nxt;
            }
            double a = Math.max(ts, t0), b = Math.min(segEnd, endLimit);
            if (b <= a) continue;
            double soc1 = toNext ? rows.get(i + 1).soc : r.soc;
            Seg s = new Seg(a, b, r.mains() ? GRID : OUTAGE);
            s.outKwh = r.out * (b - a) / 3.6e6;
            s.inKwh = r.in * (b - a) / 3.6e6;
            s.socStart = lerp(ts, segEnd, r.soc, soc1, a);
            s.socEnd = lerp(ts, segEnd, r.soc, soc1, b);
            if (s.start - cursor > 1) out.add(new Seg(cursor, s.start, NODATA));
            Seg prev = out.isEmpty() ? null : out.get(out.size() - 1);
            if (prev != null && prev.kind == s.kind && Math.abs(prev.end - s.start) <= 1) {
                prev.end = s.end;
                prev.outKwh += s.outKwh;
                prev.inKwh += s.inKwh;
                if (!Double.isNaN(s.socEnd)) prev.socEnd = s.socEnd;
            } else {
                out.add(s);
            }
            cursor = Math.max(cursor, s.end);
        }
        if (endLimit - cursor > 1) out.add(new Seg(cursor, endLimit, NODATA));
        return out;
    }

    /** Replace no-data stretches by an estimate from the neighbours (an outage wins next to a gap). */
    public static List<Seg> fillGaps(List<Seg> segs) {
        List<Seg> out = new ArrayList<>();
        for (int i = 0; i < segs.size(); i++) {
            Seg s = segs.get(i);
            if (s.kind != NODATA) {
                out.add(s);
                continue;
            }
            Seg prev = null, nxt = null;
            for (int j = i - 1; j >= 0 && prev == null; j--) {
                if (segs.get(j).kind != NODATA) prev = segs.get(j);
            }
            for (int j = i + 1; j < segs.size() && nxt == null; j++) {
                if (segs.get(j).kind != NODATA) nxt = segs.get(j);
            }
            Seg src = null;
            if (prev != null && nxt != null) {
                src = (prev.kind == nxt.kind || prev.kind == OUTAGE) ? prev : nxt;
            } else if (prev != null && s.seconds() <= TRAILING_MAX) {
                src = prev;
            }
            if (src == null) {
                out.add(s);
                continue;
            }
            double outW = src.seconds() > 0 ? src.outKwh * 3.6e6 / src.seconds() : 0;
            double inW = src.seconds() > 0 ? src.inKwh * 3.6e6 / src.seconds() : 0;
            double s0 = prev != null ? prev.socEnd : Double.NaN;
            double s1 = nxt != null ? nxt.socStart : s0;
            if (src.kind == OUTAGE && !Double.isNaN(s0) && !Double.isNaN(s1)) s1 = Math.min(s0, s1);
            Seg f = new Seg(s.start, s.end, src.kind);
            f.outKwh = outW * s.seconds() / 3.6e6;
            f.inKwh = inW * s.seconds() / 3.6e6;
            f.socStart = s0;
            f.socEnd = s1;
            f.est.add(new double[]{s.start, s.end});
            out.add(f);
        }
        return out;
    }

    public static List<Seg> merge(List<Seg> segs) {
        List<Seg> out = new ArrayList<>();
        for (Seg s : segs) {
            Seg last = out.isEmpty() ? null : out.get(out.size() - 1);
            if (last != null && last.kind == s.kind && Math.abs(last.end - s.start) <= 1) {
                last.end = s.end;
                last.outKwh += s.outKwh;
                last.inKwh += s.inKwh;
                last.est.addAll(s.est);
                last.manual.addAll(s.manual);
                if (!Double.isNaN(s.socEnd)) last.socEnd = s.socEnd;
            } else {
                out.add(s.copy());
            }
        }
        return out;
    }

    /** Chain battery levels across touching blocks without overriding measured values. */
    public static List<Seg> linkBattery(List<Seg> segs) {
        for (int i = 1; i < segs.size(); i++) {
            Seg prev = segs.get(i - 1), cur = segs.get(i);
            if (prev.kind == NODATA || cur.kind == NODATA || Math.abs(cur.start - prev.end) > 1
                    || Double.isNaN(prev.socEnd)) {
                continue;
            }
            if (Double.isNaN(cur.socStart) || cur.startEstimated()) cur.socStart = prev.socEnd;
            if (cur.kind == OUTAGE && cur.endEstimated() && !Double.isNaN(cur.socEnd) && !Double.isNaN(cur.socStart)) {
                cur.socEnd = Math.min(cur.socEnd, cur.socStart);
            }
        }
        return segs;
    }

    public static List<Seg> slice(List<Seg> segs, double t0, double t1) {
        List<Seg> out = new ArrayList<>();
        for (Seg s : segs) {
            double a = Math.max(s.start, t0), b = Math.min(s.end, t1);
            if (b <= a) continue;
            double f = s.seconds() > 0 ? (b - a) / s.seconds() : 0;
            Seg c = new Seg(a, b, s.kind);
            c.outKwh = s.outKwh * f;
            c.inKwh = s.inKwh * f;
            c.socStart = lerp(s.start, s.end, s.socStart, s.socEnd, a);
            c.socEnd = lerp(s.start, s.end, s.socStart, s.socEnd, b);
            clip(s.est, t0, t1, c.est);
            clip(s.manual, t0, t1, c.manual);
            out.add(c);
        }
        return out;
    }

    private static void clip(List<double[]> spans, double t0, double t1, List<double[]> into) {
        for (double[] e : spans) {
            double x = Math.max(e[0], t0), y = Math.min(e[1], t1);
            if (y > x) into.add(new double[]{x, y});
        }
    }

    /** The whole pipeline used by the real-outage graph. */
    public static List<Seg> real(List<Row> rows, List<Mark> marks, double t0, double t1, double now) {
        List<Seg> raw = grid(dropStale(rows), t0, t1, now);
        return linkBattery(merge(fillGaps(applyMarks(raw, resolveMarks(marks)))));
    }

    /** One schedule day: 24 letters Y N F S M G H (see schedule.py) as half-hour based segments. */
    public static List<Seg> scheduleDay(long dayTs, String hours) {
        List<Seg> out = new ArrayList<>();
        for (int h = 0; h < hours.length(); h++) {
            char c = hours.charAt(h);
            int first = c == 'N' || c == 'F' ? OUTAGE : (c == 'M' || c == 'G' ? MAYBE : GRID);
            int second = c == 'N' || c == 'S' ? OUTAGE : (c == 'M' || c == 'H' ? MAYBE : GRID);
            out.add(new Seg(dayTs + h * 3600L, dayTs + h * 3600L + 1800, first));
            out.add(new Seg(dayTs + h * 3600L + 1800, dayTs + h * 3600L + 3600, second));
        }
        return merge(out);
    }

    public static double secondsOf(List<Seg> segs, int kind) {
        double sum = 0;
        for (Seg s : segs) {
            if (s.kind == kind) sum += s.seconds();
        }
        return sum;
    }
}
